#!/usr/bin/env python3
"""Static compile-risk audit of the Darwin-only Swift (CoreML, Metal, AVFoundation, VideoToolbox, Accelerate, CoreVideo, Compression, CryptoKit, AppKit menu) on Linux.
Builds minimal STUB modules of those frameworks (written from the public API shapes; they are only as right as the signatures typed here), re-exports Darwin so
`#if canImport(...)` bodies are compiled, and runs `swiftc -typecheck -swift-version 5` over the 3D files plus a tiny AppDelegate/PPController shim. This checks every cross-file
symbol, label, optional and type in code that is otherwise parse-only here. It does NOT prove Apple's real API matches the stubs. Also: the MSL source of Stereo3DKernel is
extracted and syntax-checked with g++ against a small metal_stdlib shim, and the S3DParams (MSL) vs Params (Swift) layouts are compared.
PrepareSupport.swift is checked as a copy with st_mtimespec renamed (Linux member name); an error in one file otherwise hides all later ones. Run: SWIFTC=/path/to/swiftc python3 Tests/DarwinTypecheck/darwin_typecheck_test.py"""
def _threed_split():
    import importlib.util as _iu, pathlib as _pl
    _d = _pl.Path(__file__).resolve().parent
    while not (_d / 'Tests/Structure/threed_split.py').exists():
        assert _d != _d.parent, 'Tests/Structure/threed_split.py not found'
        _d = _d.parent
    _s = _iu.spec_from_file_location('threed_split', _d / 'Tests/Structure/threed_split.py')
    _m = _iu.module_from_spec(_s); _s.loader.exec_module(_m); return _m
